from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Base 3D heat kernel. We keep the interface in terms of DATA_TYPE so it can
# be specialized to float/double at C code generation time.
@proc
def heat_3d_base(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We update only the interior points, so n must be at least 3.
    assert n > 2

    for t in seq(0, tsteps):
        # Sweep 1: update B from A.
        # We rewrite the 7-point stencil to minimize arithmetic and memory traffic:
        #   B = 0.25 * center + 0.125 * sum(neighbors)
        # instead of the original form with repeated center terms.
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    center: DATA_TYPE
                    neighbor_sum: DATA_TYPE

                    center = A[i, j, k]

                    neighbor_sum = (
                        A[i + 1, j,     k    ] +
                        A[i - 1, j,     k    ] +
                        A[i,     j + 1, k    ] +
                        A[i,     j - 1, k    ] +
                        A[i,     j,     k + 1] +
                        A[i,     j,     k - 1]
                    )

                    B[i, j, k] = 0.25 * center + 0.125 * neighbor_sum

        # Sweep 2: update A from B (same stencil, roles of A/B swapped).
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    center: DATA_TYPE
                    neighbor_sum: DATA_TYPE

                    center = B[i, j, k]

                    neighbor_sum = (
                        B[i + 1, j,     k    ] +
                        B[i - 1, j,     k    ] +
                        B[i,     j + 1, k    ] +
                        B[i,     j - 1, k    ] +
                        B[i,     j,     k + 1] +
                        B[i,     j,     k - 1]
                    )

                    A[i, j, k] = 0.25 * center + 0.125 * neighbor_sum


# Scheduling / optimization script.
# We expose parallelism across the i-dimension in both sweeps.
# Each (i,j,k) update in a given sweep depends only on the previous array
# (A for the first sweep, B for the second), so iterations are independent.

p = heat_3d_base

# Parallelize the i-loop of the first sweep (update B from A).
i_loop_0 = p.find_loop("i #0")
p = parallelize_loop(p, i_loop_0)

# Parallelize the i-loop of the second sweep (update A from B).
i_loop_1 = p.find_loop("i #1")
p = parallelize_loop(p, i_loop_1)

# Rename the optimized procedure to the name expected by the C driver.
kernel_heat_3d = rename(p, "kernel_heat_3d")
