from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Heat-3D stencil kernel.
# The DATA_TYPE placeholder is substituted at code-generation time
# so that the same Exo kernel works for single or double precision.

@proc
def kernel_heat_3d(
    tsteps: size,
    n: size,
    A: DATA_TYPE[n, n, n] @ DRAM,
    B: DATA_TYPE[n, n, n] @ DRAM,
):
    # We only update interior points [1 .. n-2] in each dimension.
    assert n > 2

    for t in seq(0, tsteps):
        # ------------------------------------------------------------------
        # First half-step: update B from A (read A at time t, write B at t+1)
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    # Use temporaries to reduce repeated loads and arithmetic.
                    center: DATA_TYPE
                    lap: DATA_TYPE

                    center = A[i, j, k]

                    # 3D 7-point Laplacian:
                    # sum of 6 neighbors minus 6 * center
                    lap = (
                        A[i + 1, j,     k    ] +
                        A[i - 1, j,     k    ] +
                        A[i,     j + 1, k    ] +
                        A[i,     j - 1, k    ] +
                        A[i,     j,     k + 1] +
                        A[i,     j,     k - 1]
                        - 6.0 * center
                    )

                    # Original PolyBench formula:
                    #   B = 0.125 * Laplacian + center
                    B[i, j, k] = center + 0.125 * lap

        # ------------------------------------------------------------------
        # Second half-step: update A from B (read B at time t+1, write A at t+2)
        # ------------------------------------------------------------------
        for i in seq(1, n - 1):
            for j in seq(1, n - 1):
                for k in seq(1, n - 1):
                    center: DATA_TYPE
                    lap: DATA_TYPE

                    center = B[i, j, k]

                    lap = (
                        B[i + 1, j,     k    ] +
                        B[i - 1, j,     k    ] +
                        B[i,     j + 1, k    ] +
                        B[i,     j - 1, k    ] +
                        B[i,     j,     k + 1] +
                        B[i,     j,     k - 1]
                        - 6.0 * center
                    )

                    A[i, j, k] = center + 0.125 * lap


