# Scheduling / optimization
# ======================================================================

# Tile factor in the i (fastest varying spatial) dimension.
# This is a tuning knob: increase for larger caches / more cores.
I_TILE = 8

# Grab cursors to the two spatial i-loops in the time-step:
# - iB: i-loop of the B <- A update
# - iA: i-loop of the A <- B update
